import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.DTdEDYjJ.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),o={name:"guide/quickstart.md"};function r(n,t,l,h,p,d){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>先在 Mac 上完成一次真实对话，再交办一项结果可以核对的小任务。想先看界面，可以打开<a href="/openbot/#product-experience">产品首页的交互预览</a>。预览使用示例 Bot 和任务，真实对话需要安装或启动桌面应用。</p><p>有 Apple 芯片 Mac 和可用的模型 API，或已登录的受支持本机智能体，就可以从本机开始。需要跨设备执行时，再按<a href="/openbot/guide/requirements.html">使用门槛</a>选择手机连接或自建节点。</p><h2 id="_1-选择启动方式" tabindex="-1">1. 选择启动方式 <a class="header-anchor" href="#_1-选择启动方式" aria-label="Permalink to &quot;1. 选择启动方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>适用场景</th><th>前提</th></tr></thead><tbody><tr><td>Mac 安装包</td><td>日常使用、检查最终 App</td><td>Mac arm64，已取得实际交付的 DMG</td></tr><tr><td>源码启动</td><td>调试、贡献代码</td><td>Node.js 22.19.0 或更新版本、npm</td></tr><tr><td>自建 Node</td><td>让浏览器任务在自选服务器执行</td><td>已可运行的桌面端、Linux 与 Docker</td></tr></tbody></table><p>截至 2026 年 11 月 17 日，私有仓库的 GitHub Releases 最新带 Mac 安装包的是 OpenBot <strong>v0.14.0 公司试点预发布</strong>，附件包括 Apple 芯片版 DMG 和 <code>SHA256SUMS</code>。更名后的 <strong>Bot Studio 1.0.33</strong> 已在开发方本地 Mac 安装验收，同版本的安装包尚未上传到 Releases。取得仓库权限后，按所选发布页的附件和校验值下载。 <a href="https://github.com/Harzva/openbot/releases/tag/v0.14.0" target="_blank" rel="noreferrer">试点版发布（需授权）</a> · <a href="/openbot/guide/platforms.html">平台与下载</a> · <a href="/openbot/guide/status.html">验证状态</a></p><h2 id="_2-启动应用" tabindex="-1">2. 启动应用 <a class="header-anchor" href="#_2-启动应用" aria-label="Permalink to &quot;2. 启动应用&quot;">​</a></h2><p>先用发布页的 SHA-256 校验值核对 DMG，再打开 DMG，把其中的应用拖入“应用程序”。旧版试点安装包里的应用名称是 <code>OpenBot.app</code>。已有用户先退出应用并备份整个数据目录。签名、公证和安装说明以所下载版本的发布说明为准。</p><p>源码：先取得仓库，再在仓库根目录执行以下命令，使用独立开发数据目录：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Harzva/openbot.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openbot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENBOT_USERDATA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Library/Application Support/openbot-dev&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>不要让源码运行与日常安装共用数据目录。目录中会保存 Bot 身份、对话、任务、凭据与浏览器登录状态；不要把它放进 Git 仓库。</p><h2 id="复用本机智能体" tabindex="-1">复用本机智能体 <a class="header-anchor" href="#复用本机智能体" aria-label="Permalink to &quot;复用本机智能体&quot;">​</a></h2><p>如果已有受支持的 CLI 智能体，先在原程序完成安装与登录，再打开侧栏底部的“智能体工作空间”，选中已发现的执行器并显式接入。对应 Bot 固定绑定该执行器与登录上下文，使用该执行器支持的订阅与模型。</p><p>扫描到程序不等于已验证登录、额度或全部能力。自动拆解与工具编排仍按API主Bot的现有条件执行，不能把CLI单Bot聊天当作已接通CLI主脑。</p><h2 id="_3-保存一个模型连接" tabindex="-1">3. 保存一个模型连接 <a class="header-anchor" href="#_3-保存一个模型连接" aria-label="Permalink to &quot;3. 保存一个模型连接&quot;">​</a></h2><ol><li>打开设置中的 API 接入窗口，填写服务商提供的兼容 API Base URL、API Key 和准确模型名。</li><li>保存后向当前 Bot 发送一句简短消息，例如“只回复：连接已就绪”。</li><li>核对实际回复。“测试连接”检查接口可达性，收到所选模型的真实回复才验证了本次对话路径。</li><li>创建第二个 Bot 时，为它选择现有命名连接或新建连接，再分别设置模型和 Harness。</li></ol><p>每个 Bot 可以使用不同连接、模型与现有 Harness。若多个 Bot 引用同一命名连接，编辑连接地址或 Key 会影响所有引用者；只想更改一个 Bot 时，先新建连接。完整规则见<a href="/openbot/guide/models.html">模型与连接</a>。</p><h2 id="_4-验证第一项任务" tabindex="-1">4. 验证第一项任务 <a class="header-anchor" href="#_4-验证第一项任务" aria-label="Permalink to &quot;4. 验证第一项任务&quot;">​</a></h2><p>回到主 Bot，在它的设置中显式开启工具。交办一项范围小、结果容易检查的工作，例如：</p><blockquote><p>在你的文件空间写一份三行的工作清单，保存后告诉我文件名。</p></blockquote><p>出现审批时核对目标和参数，再批准或拒绝。完成后到文件空间确认内容实际保存，并在“展开工作 → 任务”查看结果。模型说“完成”不是唯一凭据。</p><p>普通 Bot 的 API 工具限于自己的浏览器屏幕；文件和组织管理权限不因开启工具自动授予普通 Bot。本机 CLI/ACP 任务还需先安装并登录对应执行器，API 配置不会替它完成安装或登录。</p><h2 id="_5-打开浏览器工作屏幕" tabindex="-1">5. 打开浏览器工作屏幕 <a class="header-anchor" href="#_5-打开浏览器工作屏幕" aria-label="Permalink to &quot;5. 打开浏览器工作屏幕&quot;">​</a></h2><p>选择 Bot 的工作屏幕，先交办只读网页任务，核对页面预览与返回结论。每个 Bot 有独立浏览器资料与屏幕；这些是 Chromium 浏览器页面，不是完整 Mac 桌面。</p><table tabindex="0"><thead><tr><th>操作</th><th>用途</th></tr></thead><tbody><tr><td>预览</td><td>查看当前真实画面，不向 Agent 授予新的观察许可</td></tr><tr><td>人工接管</td><td>停止旧 Agent 输入，自己处理页面或敏感登录</td></tr><tr><td>交还</td><td>核对画面后恢复 Agent 控制；Agent 须重新观察</td></tr><tr><td>停止</td><td>取消当前执行；已经发生的网页操作仍需核查</td></tr></tbody></table><p>浏览器中的修改操作继续逐次审批。密码、验证码等敏感登录应由你接管处理，详见<a href="/openbot/guide/computer-use.html">浏览器 Computer Use</a>。</p><h2 id="_6-让主脑协作" tabindex="-1">6. 让主脑协作 <a class="header-anchor" href="#_6-让主脑协作" aria-label="Permalink to &quot;6. 让主脑协作&quot;">​</a></h2><p>先创建并配置执行 Bot，写明职责，然后在已启用工具的 API 主 Bot 聊天头部开启“贾维斯模式”。尝试让两个执行 Bot 分别完成文字分析，再由主脑读回结果。</p><p>若需要执行 Bot 浏览网页，还须为该 Bot 显式启用工具，并明确交办浏览器任务。模式切换本身不增加权限，详情见<a href="/openbot/guide/jarvis.html">贾维斯模式</a>。</p><h2 id="_7-重启后核对记录" tabindex="-1">7. 重启后核对记录 <a class="header-anchor" href="#_7-重启后核对记录" aria-label="Permalink to &quot;7. 重启后核对记录&quot;">​</a></h2><p>退出并重新打开应用，确认 Bot 身份、连接、会话、文件和任务记录仍在。未完成任务应标为中断，不自动重跑。继续前先检查外部副作用，再明确交办下一步。</p><p>默认桌面数据目录是 <code>~/Library/Application Support/openbot</code>。配置包不包含 API Key、节点令牌或浏览器登录状态，不能代替整目录备份。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>从创建 Bot、审批、核对结果到接入外部渠道，见 <a href="/openbot/guide/using-bot-studio.html">Bot Studio 使用指南</a>。</li><li>调整模型或执行内核：<a href="/openbot/guide/models.html">模型与连接</a>、<a href="/openbot/guide/harness.html">Harness</a>。</li><li>远端执行：<a href="/openbot/deployment/self-host.html">自建 Linux Node</a>、<a href="/openbot/deployment/network.html">网络与连接</a>。</li><li>查看使用的协议、集成与对外发布物，见<a href="/openbot/development/architecture-report.html">技术架构与集成报告</a>。参与修改见<a href="/openbot/development/contributing.html">开发贡献指南</a>。</li></ul>`,34)])])}const u=a(o,[["render",r]]);export{k as __pageData,u as default};
